// Interface strings of the pages generated by the ux-lint (text-page.mjs, findings.mjs page, audit.mjs --page) and of
// the text drawn on the option previews (preview.mjs). `--lang en|pt-BR` picks the dictionary; default `en`. The
// pt-BR dictionary preserves the pages exactly as they were before the English default.
//
// Two languages are involved and they are not the same thing:
// - the page language (`--lang`): chrome, labels, annotations drawn over the capture, image alt text;
// - the product language (UX.md `content.language`, lib/lang/): text the previews put INSIDE the product
//   (state blocks, region titles, plain words for technical terms). See PRODUCT_TEXT below.
import { resolveLang } from './lang/index.mjs';

export const PAGE_LANGS = ['en', 'pt-BR'];
export const DEFAULT_PAGE_LANG = 'en';

/** Normalizes `--lang` (en, en-US, pt, pt-br…). Omitted → en. Unknown → throws with a clear message. */
export function pageLang(tag) {
  if (tag === undefined || tag === null || tag === true || tag === '') return DEFAULT_PAGE_LANG;
  const l = resolveLang(tag);
  if (!l) throw new Error(`unknown --lang "${tag}" (use ${PAGE_LANGS.join(' or ')})`);
  return l;
}

