const DICT = { en: EN, 'pt-BR': PT };

/** Strings of the page language (`--lang`, already normalized or raw). */
export function pageStrings(lang = DEFAULT_PAGE_LANG) {
  return DICT[pageLang(lang)];
}

/** Strings the runtime draws inside the capture (plain data: the runtime is serialized, functions do not travel). */
export function runtimeStrings(lang = DEFAULT_PAGE_LANG) {
  const s = pageStrings(lang).runtime;
  return { screenReader: s.screenReader, fold: s.fold('{px}'), belowFold: s.belowFold('{t}', '{px}'), regionShell: s.regionShell };
}

